import hashlib
import hmac
import time
import os
import struct
import threading
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
app.secret_key = os.urandom(32)

# In-memory stores
users_db = {}
sessions_db = {}
rate_limits = {}
lock = threading.Lock()

MAX_REQUESTS_PER_WINDOW = 100
WINDOW_SIZE_SECONDS = 60
MAX_FAILED_LOGINS = 5
LOCKOUT_DURATION = 300

class RateLimiter:
    """Token bucket rate limiter with anti-brute-force protection"""

    def __init__(self):
        self.buckets = {}  # ip -> {tokens, last_refill, failed_attempts, lockout_until}

    def _get_bucket(self, ip):
        if ip not in self.buckets:
            self.buckets[ip] = {
                'tokens': MAX_REQUESTS_PER_WINDOW,
                'last_refill': int(time.time()),
                'failed_attempts': 0,
                'lockout_until': 0
            }
        return self.buckets[ip]

    def _refill_tokens(self, bucket):
        now = int(time.time())
        elapsed = now - bucket['last_refill']
        if elapsed >= WINDOW_SIZE_SECONDS:
            bucket['tokens'] = MAX_REQUESTS_PER_WINDOW
            bucket['last_refill'] = now

    def check_rate_limit(self, ip):
        """Returns remaining tokens. Negative means rate limited."""
        bucket = self._get_bucket(ip)
        self._refill_tokens(bucket)
        bucket['tokens'] -= 1
        return bucket['tokens']

    def record_failed_login(self, ip):
        bucket = self._get_bucket(ip)
        bucket['failed_attempts'] += 1
        if bucket['failed_attempts'] >= MAX_FAILED_LOGINS:
            bucket['lockout_until'] = int(time.time()) + LOCKOUT_DURATION

    def is_locked_out(self, ip):
        bucket = self._get_bucket(ip)
        if bucket['lockout_until'] == 0:
            return False
        return int(time.time()) < bucket['lockout_until']

    def get_remaining_lockout(self, ip):
        """Returns seconds remaining in lockout as a 32-bit value for API response"""
        bucket = self._get_bucket(ip)
        if bucket['lockout_until'] == 0:
            return 0
        remaining = bucket['lockout_until'] - int(time.time())
        # Pack as signed 32-bit integer for wire format compatibility
        packed = struct.pack('>i', remaining)
        result = struct.unpack('>i', packed)[0]
        return result

    def reset_failed_attempts(self, ip):
        bucket = self._get_bucket(ip)
        bucket['failed_attempts'] = 0
        bucket['lockout_until'] = 0

rate_limiter = RateLimiter()

def hash_password(password, salt=None):
    if salt is None:
        salt = os.urandom(16)
    dk = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return salt + dk

def verify_password(stored, password):
    salt = stored[:16]
    expected = hash_password(password, salt)
    return hmac.compare_digest(stored, expected)

def generate_session_token():
    return os.urandom(32).hex()

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-Session-Token')
        if not token or token not in sessions_db:
            return jsonify({'error': 'Unauthorized'}), 401
        session = sessions_db[token]
        if time.time() > session['expires_at']:
            del sessions_db[token]
            return jsonify({'error': 'Session expired'}), 401
        g.user = session['username']
        g.role = session['role']
        return f(*args, **kwargs)
    return decorated

def require_admin(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        if g.role != 'admin':
            return jsonify({'error': 'Forbidden'}), 403
        return f(*args, **kwargs)
    return decorated

@app.before_request
def check_rate_limit():
    ip = request.remote_addr
    remaining = rate_limiter.check_rate_limit(ip)
    if remaining < 0:
        return jsonify({'error': 'Rate limited', 'retry_after': WINDOW_SIZE_SECONDS}), 429

@app.route('/register', methods=['POST'])
def register():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing fields'}), 400

    username = data['username']
    password = data['password']

    if not isinstance(username, str) or not isinstance(password, str):
        return jsonify({'error': 'Invalid types'}), 400

    if len(username) < 3 or len(username) > 32:
        return jsonify({'error': 'Username must be 3-32 chars'}), 400

    if len(password) < 8:
        return jsonify({'error': 'Password must be 8+ chars'}), 400

    with lock:
        if username in users_db:
            return jsonify({'error': 'User exists'}), 409
        users_db[username] = {
            'password_hash': hash_password(password),
            'role': 'user',
            'created_at': time.time()
        }

    return jsonify({'status': 'created'}), 201

@app.route('/login', methods=['POST'])
def login():
    ip = request.remote_addr

    # Check lockout status
    lockout_remaining = rate_limiter.get_remaining_lockout(ip)
    if lockout_remaining > 0:
        return jsonify({
            'error': 'Account locked',
            'retry_after': lockout_remaining
        }), 423

    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing fields'}), 400

    username = data['username']
    password = data['password']

    with lock:
        user = users_db.get(username)

    if not user or not verify_password(user['password_hash'], password):
        rate_limiter.record_failed_login(ip)
        return jsonify({'error': 'Invalid credentials'}), 401

    rate_limiter.reset_failed_attempts(ip)
    token = generate_session_token()
    sessions_db[token] = {
        'username': username,
        'role': user['role'],
        'expires_at': time.time() + 3600
    }

    return jsonify({'token': token, 'expires_in': 3600}), 200

@app.route('/admin/users', methods=['GET'])
@require_auth
@require_admin
def list_users():
    user_list = [{k: v for k, v in u.items() if k != 'password_hash'} 
                 for u in users_db.values()]
    return jsonify({'users': user_list}), 200

@app.route('/profile', methods=['GET'])
@require_auth
def get_profile():
    with lock:
        user = users_db.get(g.user)
    if not user:
        return jsonify({'error': 'Not found'}), 404
    return jsonify({
        'username': g.user,
        'role': user['role'],
        'created_at': user['created_at']
    }), 200

